from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    # The repeated isolated color marks the locations to receive the template.
    marker = max((c for c in counts if c != bg), key=lambda c: counts[c])
    # Find the connected non-background, non-marker template object.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] in (bg, marker) or (r,c) in seen:
                continue
            q = [(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] not in (bg,marker):
                        seen.add((ny,nx)); q.append((ny,nx))
            components.append(comp)
    comp = max(components, key=len)
    r0=min(r for r,c in comp); r1=max(r for r,c in comp)
    c0=min(c for r,c in comp); c1=max(c for r,c in comp)
    template=[row[c0:c1+1] for row in grid[r0:r1+1]]
    cr=(r1-r0)//2; cc=(c1-c0)//2
    out=[row[:] for row in grid]
    points=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==marker]
    for r,c in points:
        for i in range(len(template)):
            for j in range(len(template[0])):
                y=r+i-cr; x=c+j-cc
                if 0 <= y < h and 0 <= x < w:
                    out[y][x]=template[i][j]
    return out

